from pathlib import Path
import json,re,hashlib
r=Path('runs/online-guessing-osd-20261004');p=Path('tmp/online-guessing-osd-full-graph.json');raw=p.read_bytes();g=json.loads(raw);ns='BanditRL.OnlineGuessingSubgradient.'
scope={ns+n for n in re.findall(r'^(?:theorem|def|abbrev) (\w+)',Path('BanditRLProof/OnlineGuessingSubgradient.lean').read_text(encoding='utf-8'),re.M)}
nodes={n['name']:n for n in g['nodes']};assert scope<=set(nodes),scope-set(nodes)
edges=[e for e in g['edges'] if e['source'] in scope]
required=[(ns+'loss_subgradient_positive',ns+'loss_subdifferential_translate'),(ns+'loss_subgradient_positive','BanditRL.OnlineConvex.abs_subgradient_positive'),(ns+'loss_subgradient_zero','BanditRL.OnlineConvex.abs_subgradient_zero'),(ns+'loss_subgradient_negative','BanditRL.OnlineConvex.abs_subgradient_negative'),(ns+'example_2_32_subdifferential',ns+'loss_subgradient_positive'),(ns+'example_2_32_subdifferential',ns+'loss_subgradient_zero'),(ns+'example_2_32_subdifferential',ns+'loss_subgradient_negative'),(ns+'loss_on_unitInterval',ns+'loss_subgradient_zero'),(ns+'current_subgradient_bound','BanditRL.OnlineSubgradientDescent.currentSubgradient_mem'),(ns+'current_subgradient_bound',ns+'loss_subgradient_bound'),(ns+'loss_step_clamp','BanditRL.OnlineGradientDescent.project_unitInterval'),(ns+'guessing_prefix','BanditRL.OnlineSubgradientDescent.iterate_prefix'),(ns+'example_2_32','BanditRL.OnlineSubgradientDescent.regret_tuned'),(ns+'example_2_32',ns+'current_subgradient_bound'),(ns+'example_2_32_average_eventually',ns+'example_2_32'),(ns+'example_2_32_average_eventually','Real.tendsto_sqrt_atTop')]
for a,b in required:assert any(e['source']==a and e['target']==b and (e['kind']=='value' or e.get('also_in_value',False)) for e in edges),(a,b)
boundary={e['target'] for e in edges}-scope
v={'full_export_sha256':hashlib.sha256(raw).hexdigest(),'full_export_counts':g['counts'],'extraction':g['extraction'],'lean_version':g['lean_version'],'required_proof_value_checks':required,'scope_nodes':len(scope),'boundary_nodes':len(boundary),'nodes':[nodes[n] for n in sorted(scope|boundary)],'edges':edges}
with (r/'compiled-dependencies.json').open('w',encoding='utf-8',newline='\n') as f:json.dump(v,f,ensure_ascii=False,indent=2);f.write('\n')
print(json.dumps({'status':'passed','required_proof_value_checks':len(required),'scope_nodes':len(scope),'boundary_nodes':len(boundary),'edges':len(edges),'full_counts':g['counts']}))
